CREATE TABLE IF NOT EXISTS schema_migrations (id TEXT PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS employers (id TEXT PRIMARY KEY, name TEXT NOT NULL, aliases_json TEXT NOT NULL, logo_url TEXT);
CREATE TABLE IF NOT EXISTS sources (id TEXT PRIMARY KEY, employer_id TEXT NOT NULL REFERENCES employers(id), source_type TEXT NOT NULL, url TEXT NOT NULL, priority INTEGER NOT NULL, required INTEGER NOT NULL, active INTEGER NOT NULL, access_method TEXT NOT NULL, last_verified TEXT NOT NULL, expected_coverage TEXT NOT NULL, notes TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS runs (id INTEGER PRIMARY KEY, status TEXT NOT NULL CHECK(status IN ('running','completed','interrupted')), started_at TEXT NOT NULL, completed_at TEXT, resumed_from INTEGER);
CREATE TABLE IF NOT EXISTS source_checks (id INTEGER PRIMARY KEY, run_id INTEGER NOT NULL REFERENCES runs(id), source_id TEXT NOT NULL REFERENCES sources(id), result TEXT NOT NULL, attempted_at TEXT NOT NULL, completed_at TEXT NOT NULL, vacancies_collected INTEGER NOT NULL DEFAULT 0, failure_reason TEXT, manual_review_required INTEGER NOT NULL DEFAULT 0, UNIQUE(run_id, source_id));
CREATE TABLE IF NOT EXISTS vacancies (id INTEGER PRIMARY KEY, run_id INTEGER NOT NULL REFERENCES runs(id), source_id TEXT NOT NULL REFERENCES sources(id), source_key TEXT NOT NULL, employer_id TEXT NOT NULL REFERENCES employers(id), title TEXT NOT NULL, location TEXT, description TEXT, employment_type TEXT, requisition_id TEXT, published_at TEXT, deadline TEXT, apply_url TEXT, normalized_apply_url TEXT, source_url TEXT NOT NULL, source_type TEXT NOT NULL, evidence TEXT NOT NULL, discovered_at TEXT NOT NULL, classification_json TEXT NOT NULL, UNIQUE(run_id, source_id, source_key));
CREATE TABLE IF NOT EXISTS duplicate_matches (id INTEGER PRIMARY KEY, vacancy_id INTEGER NOT NULL REFERENCES vacancies(id), kind TEXT NOT NULL, basis TEXT NOT NULL, matched_vacancy_id INTEGER REFERENCES vacancies(id), external_reference TEXT, detail TEXT NOT NULL, UNIQUE(vacancy_id, basis, matched_vacancy_id, external_reference));
CREATE TABLE IF NOT EXISTS decisions (vacancy_id INTEGER PRIMARY KEY REFERENCES vacancies(id), action TEXT NOT NULL, edited_json TEXT NOT NULL DEFAULT '{}', decided_at TEXT NOT NULL, reviewer_note TEXT);
CREATE TABLE IF NOT EXISTS publication_manifests (id INTEGER PRIMARY KEY, run_id INTEGER NOT NULL REFERENCES runs(id), created_at TEXT NOT NULL, path TEXT NOT NULL, content_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS existing_listing_checks (id INTEGER PRIMARY KEY, opportunity_reference TEXT NOT NULL UNIQUE, status TEXT NOT NULL CHECK(status IN ('active','deadline_passed','explicitly_closed','unavailable','redirected_generic_careers','stale_without_deadline','manual_verification_required')), checked_at TEXT, notes TEXT);
